def padronizar_endereco(end):
    # Normaliza espaços e caixa, detecta prefixos comuns (r., rua, av., avenida)
    if not end or end.strip() == '':
        return ''
    s = ' '.join(end.strip().split())
    s_low = s.lower()
    prefixes = [('r.', 'rua'), ('rua', 'rua'), ('av.', 'avenida'), ('avenida', 'avenida')]
    small = {'da','de','do','das','dos','e','a','o','as','os'}
    for k, v in prefixes:
        if s_low.startswith(k):
            resto = s[len(k):].strip()
            words = resto.split()
            result_resto = ' '.join([ (w.lower() if w.lower().strip('.,') in small else w.title()) for w in words ])
            return v.title() + ' ' + result_resto
    # Nenhum prefixo conhecido: usar title() simples para manter maiúsculas em preposições como 'Da'
    return s.title()
